def validate(n):
    """Write a python function to check whether the frequency of each digit is less than or equal to the digit itself."""
    s = str(n)
    if s.startswith("-"):
        s = s[1:]
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    for ch, cnt in counts.items():
        if cnt > int(ch):
            return False
    return True
